class Base {
public:
    virtual void foo();
    virtual ~Base();
protected:
    int base_member;
};

class Derived : public Base {
public:
    Derived();
    virtual ~Derived();
    virtual Derived* clone() const;
protected:
    int derived_member;
};

// Implementation notes:
// - Each object contains a pointer to its class's vtable (vptr), typically at the start of the object.
// - The vtable is an array of function pointers generated by the compiler, one for each virtual function.
// - During construction, the vptr is set to point to the vtable of the current class, enabling correct virtual dispatch.
// - Destructors are called in reverse order of construction, with vtable pointers updated accordingly.
// - Inheritance causes subobjects to be laid out sequentially, with base class subobjects embedded within derived objects.
// - Compiler optimizations may inline functions, eliminate unused vtables, or reorder data members for cache efficiency.
